    "type": "SINGLE",
    "difficulty": 3,
    "stem": "A 64-year-old man is evaluated in the emergency receiving room of King George's Medical University Lucknow with clinical findings indicative of Multidrug-Resistant Tuberculosis MDR-TB Pulmonary Presentation. Clinical examination and investigative review confirm all-oral bedaquiline-containing regimen for 18 to 20 months under NTEP PMDT guidelines. Vitals reveal blood pressure of 126/72 mm Hg, heart rate of 82/min, respiratory rate of 14/min, and temperature of 36.6C (98.0F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of multidrug-resistant tuberculosis mdr-tb pulmonary presentation. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
    "options": [
      {
        "text": "Oral broad-spectrum fluoroquinolone monotherapy without microbiological confirmation",
        "correct": false,
        "explanation": "Incorrect: Empiric fluoroquinolones risk severe adverse effects including tendonopathy and select for multidrug-resistant pathogens when unindicated."
      },
      {
        "text": "All-oral bedaquiline-containing regimen for 18 to 20 months under NTEP PMDT guidelines",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is all-oral bedaquiline-containing regimen for 18 to 20 months under NTEP PMDT guidelines. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Oral bisphosphonate administration during active hypocalcemia",
        "correct": false,
        "explanation": "Incorrect: Potent osteoclast inhibition in hypocalcemic states triggers life-threatening cardiac arrhythmias, tetany, and laryngeal spasm."
      },
      {
        "text": "Intensive intravenous insulin bolus therapy without baseline potassium evaluation",
        "correct": false,
        "explanation": "Incorrect: Rapid insulin infusion shifts extracellular potassium intracellularly, precipitating lethal hypokalemia-induced cardiac arrest."
      },
      {
        "text": "Diagnostic lumbar puncture prior to excluding intracranial mass effect with neuroimaging",
        "correct": false,
        "explanation": "Incorrect: Performing dural puncture in the presence of focal space-occupying lesions risks fatal transtentorial or tonsillar herniation."
      }
    ],
