    "stem": "A 64-year-old man attends the outpatient department (OPD) of All India Institute of Medical Sciences (AIIMS) New Delhi with clinical findings indicative of Acute Necrotizing Pancreatitis with Infected Pancreatic Necrosis in CMC Vellore. Clinical examination and investigative review confirm step-up approach percutaneous catheter drainage followed by minimally invasive necrosectomy. Vitals reveal blood pressure of 139/85 mm Hg, heart rate of 69/min, respiratory rate of 19/min, and temperature of 37.9C (98.4F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of acute necrotizing pancreatitis with infected pancreatic necrosis in cmc vellore. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
