    "difficulty": 3,
    "stem": "A 29-year-old man is evaluated in the emergency receiving room of King George's Medical University Lucknow with clinical findings indicative of Acute Post-Streptococcal Glomerulonephritis APSGN in 8-Year-Old. Clinical examination and investigative review confirm salt and water restriction, loop diuretic furosemide for hypertension and edema, and rest. Vitals reveal blood pressure of 125/77 mm Hg, heart rate of 77/min, respiratory rate of 19/min, and temperature of 36.9C (98.3F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of acute post-streptococcal glomerulonephritis apsgn in 8-year-old. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
    "options": [
      {
        "text": "Salt and water restriction, loop diuretic furosemide for hypertension and edema, and rest",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is salt and water restriction, loop diuretic furosemide for hypertension and edema, and rest. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Endoscopic mucosal resection without preceding cross-sectional imaging",
        "correct": false,
        "explanation": "Incorrect: Endoscopic resection of deep lesions without locoregional staging risks transmural gastrointestinal perforation and tumor seeding."
      },
      {
        "text": "Empiric anti-tubercular therapy based solely on tuberculin skin test positivity",
        "correct": false,
        "explanation": "Incorrect: Latent immunological reactivity without microbiological confirmation does not justify multi-agent hepatotoxic anti-tubercular therapy."
      },
      {
        "text": "Intravenous sodium bicarbonate bolus in mild compensated ketoacidosis",
        "correct": false,
        "explanation": "Incorrect: Alkalinization in mild acidemia paradoxically causes paradoxical CSF acidosis, hypokalemia, and delayed ketone clearance."
      },
      {
        "text": "Empiric broad-spectrum antifungal therapy as sole medical intervention",
        "correct": false,
        "explanation": "Incorrect: Antifungal therapy is inappropriate in the absence of documented microbiological or radiological evidence of invasive fungal disease."
      }
    ],
    "explanation": "Educational Objective: Understand the diagnosis, guideline-directed management, and clinical rationale for Acute Post-Streptococcal Glomerulonephritis APSGN in 8-Year-Old.\\n\\nClinical Discussion: This clinical presentation corresponds to Acute Post-Streptococcal Glomerulonephritis APSGN in 8-Year-Old. The cornerstone of management involves salt and water restriction, loop diuretic furosemide for hypertension and edema, and rest. Clinical decision-making prioritizes rapid diagnosis, stabilization, and adherence to established clinical guidelines. Alternative choices represent suboptimal management strategies, delayed interventions, or therapies lacking efficacy in this specific clinical presentation.",
    "objective": "Understand the guideline-directed management and pathophysiological basis of Acute Post-Streptococcal Glomerulonephritis APSGN in 8-Year-Old.",
